import type { HousePlan, Rect, Room } from '../plan/types';

/**
 * Modern Luxe false ceiling, generated by rule from each room's outline (no hand placement):
 * a gypsum perimeter band dropped below the slab, a recessed centre, a hidden LED cove on a shelf at the
 * band's inner edge washing light up onto the recess, and a slim profile-light line in the band's underside.
 *
 * Output is plain boxes (plan feet, z relative to the level floor) plus glow strips for the renderer.
 */
export interface CeilingBox { level: number; rect: Rect; z0: number; z1: number; mat: 'ceilingBand' | 'glow' }
/** A soft light-wash decal: `rect` on a plane at height z; `fadeTo` says which side fades out. */
export interface GlowWash { level: number; rect: Rect; z: number; fadeTo: 'x+' | 'x-' | 'y+' | 'y-'; face: 'down' | 'side' }

export interface FalseCeilingSpec {
  band: number;      // band width, ft
  drop: number;      // band underside below slab, ft
  shelf: number;     // cove shelf depth beyond the band
  minRoom: number;   // smallest room side that gets a false ceiling
  skip: RegExp;      // rooms that keep a plain ceiling
}

export const MODERN_LUXE_CEILING: FalseCeilingSpec = {
  band: 1.6, drop: 1.0, shelf: 0.4, minRoom: 6,
  skip: /terrace|porch|yard|balcony|passage|lobby|bay|landing|washroom|toilet|pantry/i,
};

const overlaps = (a: Rect, b: Rect) => a[0] < b[2] && a[2] > b[0] && a[1] < b[3] && a[3] > b[1];

export function falseCeilings(plan: HousePlan, spec = MODERN_LUXE_CEILING) {
  const CH = plan.ceilingHeight;
  const boxes: CeilingBox[] = [], washes: GlowWash[] = [];
  // stairwells: anything a flight or landing passes under (on this level or rising from it) is kept clear
  const stairRects = (level: number): Rect[] => [
    ...plan.flights.filter((f) => f.level === level).map((f): Rect => (f.axis === 'x'
      ? [Math.min(f.from, f.to), f.c1, Math.max(f.from, f.to), f.c2] : [f.c1, Math.min(f.from, f.to), f.c2, Math.max(f.from, f.to)])),
    ...plan.landings.filter((l) => l.level === level).map((l) => l.rect),
  ];

  for (const room of plan.rooms) {
    if (spec.skip.test(room.name)) continue;
    const [x1, y1, x2, y2] = room.rect;
    if (x2 - x1 < spec.minRoom || y2 - y1 < spec.minRoom) continue;
    addRoom(room, stairRects(room.level));
  }
  return { boxes, washes };

  function addRoom(room: Room, blocked: Rect[]) {
    const L = room.level, [x1, y1, x2, y2] = room.rect, b = spec.band, s = spec.shelf;
    const zb = CH - spec.drop;
    // four band sides: [band rect, inner edge direction]
    const sides: { r: Rect; dir: 'x+' | 'x-' | 'y+' | 'y-' }[] = [
      { r: [x1, y1, x2, y1 + b], dir: 'y+' },
      { r: [x1, y2 - b, x2, y2], dir: 'y-' },
      { r: [x1, y1 + b, x1 + b, y2 - b], dir: 'x+' },
      { r: [x2 - b, y1 + b, x2, y2 - b], dir: 'x-' },
    ];
    for (const { r, dir } of sides) {
      if (blocked.some((k) => overlaps(r, k))) continue;
      boxes.push({ level: L, rect: r, z0: zb, z1: CH, mat: 'ceilingBand' });
      // profile light: slim line along the middle of the band's underside
      const mid = dir[0] === 'y' ? (r[1] + r[3]) / 2 : (r[0] + r[2]) / 2;
      const inset = 0.6;
      const line: Rect = dir[0] === 'y' ? [r[0] + inset, mid - 0.04, r[2] - inset, mid + 0.04] : [mid - 0.04, r[1] + inset, mid + 0.04, r[3] - inset];
      boxes.push({ level: L, rect: line, z0: zb - 0.015, z1: zb, mat: 'glow' });
      // cove: shelf + upstand at the band's inner edge, LED strip on the shelf
      let shelf: Rect, up: Rect, led: Rect, wash: Rect, face: Rect;
      if (dir === 'y+') { const e = r[3]; shelf = [r[0], e, r[2], e + s]; up = [r[0], e + s - 0.06, r[2], e + s]; led = [r[0], e, r[2], e + 0.08]; wash = [r[0], e, r[2], e + 2.4]; face = [r[0], e, r[2], e]; }
      else if (dir === 'y-') { const e = r[1]; shelf = [r[0], e - s, r[2], e]; up = [r[0], e - s, r[2], e - s + 0.06]; led = [r[0], e - 0.08, r[2], e]; wash = [r[0], e - 2.4, r[2], e]; face = [r[0], e, r[2], e]; }
      else if (dir === 'x+') { const e = r[2]; shelf = [e, r[1], e + s, r[3]]; up = [e + s - 0.06, r[1], e + s, r[3]]; led = [e, r[1], e + 0.08, r[3]]; wash = [e, r[1], e + 2.4, r[3]]; face = [e, r[1], e, r[3]]; }
      else { const e = r[0]; shelf = [e - s, r[1], e, r[3]]; up = [e - s, r[1], e - s + 0.06, r[3]]; led = [e - 0.08, r[1], e, r[3]]; wash = [e - 2.4, r[1], e, r[3]]; face = [e, r[1], e, r[3]]; }
      boxes.push({ level: L, rect: shelf, z0: zb, z1: zb + 0.08, mat: 'ceilingBand' });
      boxes.push({ level: L, rect: up, z0: zb + 0.08, z1: zb + 0.2, mat: 'ceilingBand' });
      boxes.push({ level: L, rect: led, z0: zb + 0.08, z1: zb + 0.11, mat: 'glow' });
      washes.push({ level: L, rect: wash, z: CH - 0.01, fadeTo: dir, face: 'down' });
      washes.push({ level: L, rect: face, z: zb + 0.11, fadeTo: dir, face: 'side' });
    }
  }
}
